Компоненты скелетонов
Когда в самом начале мы прошлись всем страницам приложения, которые нуждаются в индикации загрузки, стали понятны повторяющиеся паттерны интерфейса, под которые необходимо создать переиспользуемые и настраиваемые компоненты.
Вот пример скелетон-компонента
вертикальных карточек
со всеми настройками, которые отчасти присущи и другим компонентам.
// Карточки сгруппированы (например, по дате)
@Input() grouped: boolean;
// Высота карточки больше базовой
@Input() large: boolean;
// Высота карточки меньше базовой
@Input() small: boolean;
// Количество карточек
@Input() count = 3;

cards: unknown[] = [];

ngOnInit(): void {
 this.cards = new Array(this.count);
}
<div class="cards-container-skeleton"
 [class.large]="large"
 [class.small]="small">
 <div *ngIf="grouped"
 class="cards-header-skeleton skeleton">
 </div>

 <div *ngFor="let _ of cards"
 class="card-skeleton skeleton">
 </div>
</div>
.cards-container-skeleton {
 height: inherit;
 margin: inherit;
 padding: inherit;
 overflow: scroll;
}

.cards-header-skeleton {
 height: 35px;
 width: 200px;
 border-radius: 15px;
 margin-bottom: 15px;
}

.card-skeleton {
 height: 180px;
 border-radius: 15px;
 margin-bottom: 15px;
}

.cards-container-skeleton.large .card-skeleton {
 height: 330px;
}

.cards-container-skeleton.small .card-skeleton {
 height: 92px;
 margin-bottom: 10px;
}
