Сделаем еще одну версию detour - во время compress будет сохранять индексы только непустых регистров (в буфер
idx
), и expand будет итерировать по ним:
template <bool Skip>
 size_t detour_compact(float* dst, const size_t n, const auto w, auto f, auto mask) {
 float* ptr = tmp.data();
 size_t k = 0;
 for (size_t i = 0; i < n; i += 16) {
 // начало цикла как в detour

 if constexpr (Skip)
 if (vmaxvq_u32(vaddq_u32(vaddq_u32(m[0], m[1]), vaddq_u32(m[2], m[3]))) == 0) continue;

 std::array<uint32_t, 4> sk;
 for (size_t j = 0; j < 4; ++j) sk[j] = vaddvq_u32(vandq_u32(m[j], w));
 for (size_t j = 0; j < 4; ++j) {
 s[k] = sk[j];
 idx[k] = i + 4 * j;
 k += bool(sk[j]);
 }
 // конец цикла как в detour
 }
 // тут тоже как в detour

 for (size_t j = 0; j < 3; ++j) s[k + j] = 0, idx[k + j] = 0;
 // 2 фаза как в detour
 k = (k + 3) & ~size_t(3);
 for (size_t i = 0; i < k; i += 4) {
 std::array<uint32_t, 4> sk;
 for (size_t j = 0; j < 4; ++j) sk[j] = s[i + j];
 std::array<float32x4_t, 4> a;
 for (size_t j = 0; j < 4; ++j) a[j] = vld1q_f32(dst + idx[i + j]);
 // и здесь как в detour
 for (size_t j = 0; j < 4; ++j)
 vst1q_f32(dst + idx[i + j], vreinterpretq_f32_u8(vqtbl2q_u8(tbl[j], index[j])));
 ptr += off[3] + (sk[3] >> 4);
 }

 return size;
 }
k (кол-во непустых регистров) до expand округляется вверх до кратного 4, чтобы после анролла не обрабатывать остаток.
Нету веток в горячих циклах - они бы убили скорость, поэтому compress придется выполнить для всех четырех регистров. Вместо веток позиция текущего элемента сдвигается на
bool(sk)
